def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    # Final-round domination: the opponent cannot punish after this match.
    if n >= 99:
        return 'D'

    # Basic counts and recent statistics.
    opp_c = 0
    my_c = 0
    for m, o in history:
        if m == 'C':
            my_c += 1
        if o == 'C':
            opp_c += 1

    opp_rate = opp_c / float(n)

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    rec10_c = 0
    for i in range(start10, n):
        if history[i][1] == 'C':
            rec10_c += 1
    rec10_d = (n - start10) - rec10_c

    start20 = n - 20
    if start20 < 0:
        start20 = 0
    rec20_c = 0
    for i in range(start20, n):
        if history[i][1] == 'C':
            rec20_c += 1
    rec20_d = (n - start20) - rec20_c

    # Streaks.
    opp_streak_D = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_streak_D += 1
        i -= 1

    my_streak_D = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_streak_D += 1
        i -= 1

    # Learn whether opponent forgives our exploitation.
    # A clean exploit test: opponent cooperated last round, we defect and they also
    # cooperate in the executed pair; their next action reveals forgiveness/punishment.
    forgiving = 0
    punishing = 0
    rforgive = 0
    rpunish = 0

    for i in range(n):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if i == 0 or history[i - 1][1] == 'C':
                if i + 1 < n:
                    if history[i + 1][1] == 'C':
                        forgiving += 1
                        if i >= start20:
                            rforgive += 1
                    else:
                        punishing += 1
                        if i >= start20:
                            rpunish += 1

    tests = forgiving + punishing
    recent_tests = rforgive + rpunish

    if tests == 0:
        exploit_state = 0       # unknown
    else:
        if recent_tests > 0:
            f = rforgive
            p = rpunish
        else:
            f = forgiving
            p = punishing

        t = f + p
        if t == 0:
            exploit_state = 0
        elif f == 0:
            exploit_state = -1  # known retaliatory
        elif p == 0:
            exploit_state = 1 if (opp_c == n or rec10_c >= 6) else -1
        else:
            ratio = f / float(t)
            if ratio >= 0.60 and rec10_c >= 5:
                exploit_state = 1
            elif ratio <= 0.35 or rec10_c <= 3:
                exploit_state = -1
            else:
                exploit_state = -1

    if n < 6:
        friendly = (opp_c == n) or (opp_rate >= 0.7)
    else:
        friendly = ((opp_rate >= 0.55 and rec10_c >= 6) or
                    (opp_rate >= 0.7) or
                    (opp_c == n))

    if n < 8:
        hostile = (n >= 5 and opp_rate <= 0.1)
    else:
        hostile = ((opp_rate <= 0.2 or rec10_c <= 2) or
                   (n >= 20 and rec20_c <= 3))

    # If we have evidence that this opponent can be exploited, exploit it in a
    # controlled way. Against pure cooperators keep defecting; otherwise alternate
    # D/C to avoid triggering conditional punishment cycles.
    if exploit_state == 1 and not hostile:
        if last_opp == 'C':
            if opp_c == n and forgiving >= 2:
                return 'D'

            if last_my == 'D':
                # Continue pressure only while recent evidence is clean and they remain cooperative.
                if rpunish == 0 and rforgive >= 3 and rec10_c >= 7:
                    return 'D'
                return 'C'

            if (opp_c == n or
                rec10_c >= 8 or
                (forgiving >= 3 and punishing == 0) or
                (forgiving > punishing and rec10_c >= 6)):
                return 'D'
            return 'C'
        else:
            if friendly and opp_streak_D <= 2:
                return 'C'
            return 'D'

    # Single exploratory test against strongly cooperative opponents when we have
    # not yet learned whether they forgive our defection.
    if exploit_state == 0 and n >= 3 and last_opp == 'C' and last_my == 'C':
        if opp_c == n or rec10_c >= 9 or opp_rate >= 0.72:
            return 'D'
        if friendly and n < 35 and rng.random() < 0.05:
            return 'D'

    # Against clearly uncooperative opponents, take the safe payoff.
    if hostile:
        return 'D'

    # Default: retaliatory, but try to restore cooperation after short punishment
    # or mutual-defection loops against otherwise cooperative opponents.
    if last_opp == 'D':
        # If we cooperated last round and they defected immediately after having
        # punished our previous defection, keep extending cooperation to restore CC.
        if (last_my == 'C' and
            n >= 2 and
            history[-2][0] == 'D' and
            history[-2][1] == 'C'):
            if opp_streak_D <= 2:
                return 'C'

        # Mutual defection: against mostly cooperative opponents, break the cycle.
        if (last_my == 'D' and
            friendly and
            opp_streak_D <= 2 and
            rec10_c >= 5):
            return 'C'

        return 'D'

    # Opponent cooperated last. If we defected last but are not known exploitable,
    # cooperate to avoid a punishment loop.
    if last_my == 'D' and friendly:
        return 'C'

    return 'C'
